<?php
declare(strict_types=1);
/** Explicitly selected contact records and immutable document versions. */
final class SecureObjectSync {
 private static function peer(string $id):array{return Db::one('SELECT * FROM platform_peers WHERE id=? AND revoked=0',[$id])??throw new InvalidArgumentException(t('Pair this device first.'));}
 private static function snapshot(string $kind,int $id):?array{
  if($kind==='contacts'){try{$r=LifePlanningService::get('contacts',$id);}catch(InvalidArgumentException){return null;}return array_intersect_key($r,array_flip(['name','phone','email','birthday','next_followup','notes']));}
  $r=Db::one('SELECT * FROM documents WHERE id=? AND deleted_at IS NULL',[$id]);if(!$r)return null;$file=DocumentService::path($r,DATA);return ['title'=>$r['title'],'category'=>$r['category'],'notes'=>$r['notes']??'','original_name'=>$r['original_name'],'sha256'=>hash_file('sha256',$file)];
 }
 public static function packet(string $peerId,array $contacts,array $documents):string{
  $peer=self::peer($peerId);$me=DeviceSyncService::identity();$items=[];$total=0;if(count($contacts)>100||count($documents)>20)throw new InvalidArgumentException(t('Select at most 100 contacts and 20 documents.'));
  foreach(['contacts'=>$contacts,'documents'=>$documents]as $kind=>$ids){if(!$ids)continue;if(!module_enabled($kind==='contacts'?'LifePlanning':'Documents'))throw new InvalidArgumentException(t('Enable the module before sharing its records.'));foreach(array_unique($ids)as $raw){$id=record_id($raw);$data=self::snapshot($kind,$id);if(!$data)throw new InvalidArgumentException(t('Selected sync record is missing.'));$item=['kind'=>$kind,'id'=>SyncIdentity::forRow($kind,$id),'record'=>$data];if($kind==='documents'){$r=Db::one('SELECT * FROM documents WHERE id=?',[$id]);$file=DocumentService::path($r,DATA);$total+=filesize($file);if($total>5242880)throw new InvalidArgumentException(t('Selected attachments exceed 5 MiB per packet.'));$item['file']=base64_encode(file_get_contents($file));}$items[]=$item;}}
  $nonce=random_bytes(24);$key=sodium_crypto_box_keypair_from_secretkey_and_publickey(sodium_crypto_box_secretkey($me['key']),base64_decode($peer['public_key']));$cipher=sodium_crypto_box(json_encode(['version'=>2,'items'=>$items],JSON_THROW_ON_ERROR),$nonce,$key);return json_encode(['v'=>2,'from'=>$me['id'],'to'=>$peerId,'nonce'=>base64_encode($nonce),'data'=>base64_encode($cipher)],JSON_THROW_ON_ERROR);
 }
 public static function preview(string $packet):array{
  if(strlen($packet)>12582912)throw new InvalidArgumentException(t('Record packet exceeds 12 MiB.'));$p=json_decode($packet,true,16,JSON_THROW_ON_ERROR);$me=DeviceSyncService::identity();if(!is_array($p)||($p['v']??0)!==2||($p['to']??'')!==$me['id']||!is_string($p['from']??null))throw new InvalidArgumentException(t('Record packet is not for this device.'));$peer=self::peer($p['from']);$nonce=is_string($p['nonce']??null)?base64_decode($p['nonce'],true):false;$cipher=is_string($p['data']??null)?base64_decode($p['data'],true):false;if(!$nonce||strlen($nonce)!==24||!$cipher)throw new InvalidArgumentException(t('Invalid encryption fields.'));$key=sodium_crypto_box_keypair_from_secretkey_and_publickey(sodium_crypto_box_secretkey($me['key']),base64_decode($peer['public_key']));$plain=sodium_crypto_box_open($cipher,$nonce,$key);if($plain===false)throw new InvalidArgumentException(t('Record packet authentication failed.'));$payload=json_decode($plain,true,32,JSON_THROW_ON_ERROR);if(!is_array($payload['items']??null)||count($payload['items'])>120)throw new InvalidArgumentException(t('Too many record items.'));$out=[];$seen=[];$total=0;
  foreach($payload['items']as $item){$kind=$item['kind']??'';$uuid=$item['id']??'';$d=$item['record']??null;if(!in_array($kind,['contacts','documents'],true)||!is_string($uuid)||!preg_match('/^[a-f0-9]{64}:'.preg_quote($kind,'/').':[1-9][0-9]*$/D',$uuid)||isset($seen[$uuid])||!is_array($d))throw new InvalidArgumentException(t('Invalid or repeated record identity.'));$seen[$uuid]=true;if(!module_enabled($kind==='contacts'?'LifePlanning':'Documents'))throw new InvalidArgumentException(t('Enable the destination record module.'));
   if($kind==='contacts'){$fields=['name','phone','email','birthday','next_followup','notes'];foreach($fields as $f){$v=$d[$f]??null;if(!is_string($v)&&!($v===null&&in_array($f,['birthday','next_followup'],true)))throw new InvalidArgumentException(t('Invalid contact field.'));if(is_string($v)&&(mb_strlen($v)>2000||str_contains($v,"\0")))throw new InvalidArgumentException(t('Contact field too long.'));if(in_array($f,['birthday','next_followup'],true)&&$v!==null)valid_date($v);}if(trim($d['name'])==='')throw new InvalidArgumentException(t('Contact name is required.'));$d=array_intersect_key($d,array_flip($fields));}
   else{foreach(['title','category','notes','original_name','sha256']as $f)if(!is_string($d[$f]??null))throw new InvalidArgumentException(t('Invalid document metadata.'));if(mb_strlen($d['title'])>200||trim($d['title'])===''||mb_strlen($d['notes'])>3000||!in_array($d['category'],DocumentService::CATEGORIES,true)||!preg_match('/^[a-f0-9]{64}$/D',$d['sha256']))throw new InvalidArgumentException(t('Invalid document details.'));$bytes=is_string($item['file']??null)?base64_decode($item['file'],true):false;if(!$bytes)throw new InvalidArgumentException(t('Document payload is empty.'));$total+=strlen($bytes);if($total>5242880||!hash_equals($d['sha256'],hash('sha256',$bytes)))throw new InvalidArgumentException(t('Document size or hash validation failed.'));$temp=tempnam(sys_get_temp_dir(),'lifeos-sync-');try{file_put_contents($temp,$bytes);DocumentService::inspect($temp,$d['original_name']);}finally{unlink($temp);}$item['bytes']=$bytes;$d=array_intersect_key($d,array_flip(['title','category','notes','original_name','sha256']));}
   $map=Db::one('SELECT * FROM platform_object_maps WHERE peer=? AND uuid=?',[$peer['id'],$uuid]);$native=Db::one('SELECT row_id FROM platform_local_ids WHERE kind=? AND uuid=?',[$kind,$uuid]);$id=$map['local_id']??$native['row_id']??null;$local=$id?self::snapshot($kind,(int)$id):null;$base=$map?json_decode($map['base_json'],true):null;$conflict=($local!==null&&$local!==$d&&$local!==$base)||($map&&$local===null);$out[]=['kind'=>$kind,'id'=>$uuid,'record'=>$d,'bytes'=>$item['bytes']??null,'local'=>$local,'local_id'=>$id,'conflict'=>$conflict];
  }return ['peer'=>$peer['id'],'hash'=>hash('sha256',$packet),'rows'=>$out];
 }
 public static function apply(string $packet,array $choices):void{
  $p=self::preview($packet);$created=[];try{Db::tx(function()use($p,$choices,&$created){if(Db::one('SELECT hash FROM platform_sync_packets WHERE hash=?',[$p['hash']]))throw new InvalidArgumentException(t('Packet already processed.'));foreach($p['rows']as $item){$d=$item['record'];$kind=$item['kind'];$choice=$choices[$item['id']]??'';if($item['conflict']&&!in_array($choice,['local','remote'],true))throw new InvalidArgumentException(t('Resolve all record conflicts.'));if($item['conflict']&&$choice==='local')continue;$id=$item['local_id'];if($item['local']!==$d){if($kind==='contacts'){$values=array_map(fn($v)=>$v===null?'':(string)$v,$d);$id=LifePlanningService::save('contacts',$values,$item['local']===null?null:(int)$id,false);}else{$temp=tempnam(sys_get_temp_dir(),'lifeos-sync-');try{file_put_contents($temp,$item['bytes']);$id=DocumentService::store($temp,$d['original_name'],$d['title'],$d['category'],$d['notes'],DATA);$row=Db::one('SELECT * FROM documents WHERE id=?',[$id]);$created[]=DocumentService::path($row,DATA);}finally{unlink($temp);}}}if(!$id)throw new InvalidArgumentException(t('Missing local record identity.'));if($item['local_id']&&$item['local_id']!==$id)Db::run('DELETE FROM platform_local_ids WHERE kind=? AND row_id=?',[$kind,$item['local_id']]);SyncIdentity::bind($kind,(int)$id,$item['id']);Db::run('INSERT INTO platform_object_maps(peer,uuid,kind,local_id,base_json) VALUES(?,?,?,?,?) ON CONFLICT(peer,uuid) DO UPDATE SET local_id=excluded.local_id,base_json=excluded.base_json',[$p['peer'],$item['id'],$kind,$id,json_encode($d,JSON_THROW_ON_ERROR)]);}Db::run('INSERT INTO platform_sync_packets(hash) VALUES(?)',[$p['hash']]);PlatformService::audit('records-synced',$p['peer'].'; '.count($p['rows']).' explicitly selected records reviewed');});}catch(Throwable $e){foreach($created as $path)if(is_file($path))unlink($path);throw $e;}
 }
}
